pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address deployer;

    function setUp() public {
        deployer = address(this);
        c = new C(address(this));
    }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));
        vm.prank(caller);
        // The property: owner() always returns the deployer's address.
        assertTrue(c.owner() == deployer);
    }
}

