pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address /* spender unused */) public {
        // The reference contract's name() returns the stored name ("DCF Token").
        // The mutant returns a hardcoded string "FixedName".
        // This test checks that for any random address, the name() is the same.
        // Since the reference always returns "DCF Token", and the mutant returns a different constant,
        // the property "name() returns the same string for all callers" holds for the reference
        // but fails for the mutant.

        // Call name() twice with different callers (simulated via prank) to ensure it's constant.
        address randomUser1 = address(uint160(uint256(keccak256(abi.encodePacked(block.timestamp)))));
        address randomUser2 = address(uint160(uint256(keccak256(abi.encodePacked(block.timestamp + 1)))));

        vm.prank(randomUser1);
        string memory name1 = c.name();
        vm.prank(randomUser2);
        string memory name2 = c.name();

        assertTrue(keccak256(bytes(name1)) == keccak256(bytes(name2)), "name() should return the same value for all callers");
    }
}

