// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address from, address to, uint256 amount) public {
        vm.assume(from != address(0) && to != address(0) && from != to);
        vm.assume(amount <= 1e30); // avoid overflow

        uint256 supplyBefore = c.totalSupply();

        // Try to transfer tokens; we only care about the totalSupply invariance
        (bool success, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));

        if (!success) {
            // If transfer reverted, totalSupply should still be the same
            assertTrue(c.totalSupply() == supplyBefore, "totalSupply changed after failed transfer");
        } else {
            // If transfer succeeded, totalSupply should be unchanged (no minting/burning)
            assertTrue(c.totalSupply() == supplyBefore, "totalSupply changed after successful transfer");
        }
    }
}

