// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender1, address sender2, address to, uint256 amount) public {
        // Ensure valid addresses that are not blacklisted and amount is reasonable
        vm.assume(sender1 != address(0) && sender1 != address(c) && sender1 != to);
        vm.assume(sender2 != address(0) && sender2 != address(c) && sender2 != to);
        vm.assume(sender1 != sender2);
        vm.assume(to != address(0) && to != address(c));
        vm.assume(amount > 0 && amount <= 1_000_000 ether);

        // Give some tokens to sender1 and sender2 via transfer from original minter (address(this))
        uint256 initialBalance = c.balanceOf(address(this));
        if (initialBalance >= amount * 2) {
            vm.prank(address(this));
            c.transfer(sender1, amount);
            vm.prank(address(this));
            c.transfer(sender2, amount);
        } else {
            vm.assume(false);
        }

        // Perform transfers from sender1 and sender2
        vm.prank(sender1);
        (bool success1, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));
        vm.prank(sender2);
        (bool success2, ) = address(c).call(abi.encodeWithSignature("transfer(address,uint256)", to, amount));

        vm.assume(success1 && success2);

        // Read totalSupply() from two different accounts
        uint256 supplyFromSender1;
        uint256 supplyFromSender2;
        vm.prank(sender1);
        supplyFromSender1 = c.totalSupply();
        vm.prank(sender2);
        supplyFromSender2 = c.totalSupply();

        assertTrue(supplyFromSender1 == supplyFromSender2);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address sender, address recipient, uint256 amount) public {
        vm.assume(sender != address(0) && recipient != address(0) && sender != recipient);
        vm.assume(sender != address(c) && recipient != address(c));
        vm.assume(amount > 0 && amount <= c.balanceOf(sender));

        // Ensure sender has tokens
        vm.prank(c.owner());
        c.transfer(sender, amount);

        uint256 totalSupplyBefore = c.totalSupply();
        uint256 senderBalanceBefore = c.balanceOf(sender);

        // Perform transfer
        vm.prank(sender);
        c.transfer(recipient, amount);

        uint256 totalSupplyAfter = c.totalSupply();
        uint256 senderBalanceAfter = c.balanceOf(sender);
        uint256 recipientBalanceAfter = c.balanceOf(recipient);

        // General rule: totalSupply is at least the sum of balances of non-excluded accounts
        // Excluded accounts: address(0) and the contract itself (which might accumulate fees)
        uint256 sumNonExcluded = senderBalanceAfter + recipientBalanceAfter;
        // Also include the owner's remaining balance after initial mint
        uint256 ownerBalance = c.balanceOf(c.owner());
        sumNonExcluded += ownerBalance;

        assertTrue(totalSupplyAfter >= sumNonExcluded);
    }
}

