pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address from, address to, uint256 amount) public {
        // Bound amount to avoid overflow issues; from can be zero but should not be address(0) for transfer to succeed
        vm.assume(from != address(0) && to != address(0));
        vm.assume(amount <= c.balanceOf(from));
        // Drive: as 'from', transfer to 'to'
        vm.prank(from);
