    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address spender, uint256 addedValue) public {
        // Ensure spender is not the zero address so _approve does not revert
        vm.assume(spender != address(0));
        // bound addedValue to avoid overflow in allowance(old) + addedValue
        addedValue = bound(addedValue, 0, type(uint256).max - c.allowance(address(this), spender));
        bool success = c.increaseAllowance(spender, addedValue);
        assertTrue(success, "increaseAllowance should return true");
    }
}

