pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address spender, uint256 initialAllowance, uint256 addedValue) public {
        // Ensure non-zero addresses for spender and owner to avoid revert on approve
        vm.assume(owner != address(0));
        vm.assume(spender != address(0));
        // Bound addedValue to avoid overflow issues
        addedValue = bound(addedValue, 0, type(uint256).max - initialAllowance);
        // Set initial allowance via approve
        vm.prank(owner);
        c.approve(spender, initialAllowance);
        // Record allowance before increase
        uint256 allowanceBefore = c.allowance(owner, spender);
        // Call increaseAllowance as owner
        vm.prank(owner);
        bool didIncrease = c.increaseAllowance(spender, addedValue);
        // Assert that the return value is true (both P and M return true)
        assertTrue(didIncrease);
        // The general rule: after increaseAllowance, allowance equals allowanceBefore + addedValue
        uint256 allowanceAfter = c.allowance(owner, spender);
        assertTrue(allowanceAfter == allowanceBefore + addedValue, "allowance not increased correctly");
    }
}

