pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address _spender, uint256 _subtractedValue) public {
        vm.assume(_spender != address(0));
        // given some initial allowance
        uint256 initialAllowance = 1000;
        // approve the spender
        vm.prank(address(this));
        c.approve(_spender, initialAllowance);
        // record allowance before decrease
        uint256 allowanceBefore = c.allowance(address(this), _spender);
        // bound subtractedValue to not exceed allowance
        vm.assume(_subtractedValue <= allowanceBefore);
        // call decreaseAllowance
        c.decreaseAllowance(_spender, _subtractedValue);
        // check that the new allowance equals the previous allowance minus the subtracted value
        uint256 expectedAllowance = allowanceBefore - _subtractedValue;
        assertTrue(c.allowance(address(this), _spender) == expectedAllowance);
    }
}

