pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    address alice = address(0x123);
    address bob = address(0x456);

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address spender, uint256 initialAllowance, uint256 subtractedValue) public {
        vm.assume(initialAllowance >= subtractedValue);
        vm.assume(spender != address(0));
        // Setup: alice approves spender with initialAllowance
        vm.prank(alice);
        c.approve(spender, initialAllowance);
        // Store current allowance before decrease
        uint256 allowanceBefore = c.allowance(alice, spender);
        // Call decreaseAllowance as alice to reduce allowance
        vm.prank(alice);
        bool success = c.decreaseAllowance(spender, subtractedValue);
        if (success) {
            uint256 allowanceAfter = c.allowance(alice, spender);
            // General rule: new allowance equals old allowance minus subtracted value
            assertTrue(allowanceAfter == allowanceBefore - subtractedValue, "allowance not decreased correctly");
        }
    }
}

