pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address owner, address spender, uint256 oldAllowance, uint256 subtractedValue) public {
        vm.assume(owner != address(0) && spender != address(0));
        vm.assume(oldAllowance >= subtractedValue);

        // Set initial allowance
        vm.prank(owner);
        c.approve(spender, oldAllowance);

        // Record allowance before decreaseAllowance
        uint256 allowanceBefore = c.allowance(owner, spender);

        // Call decreaseAllowance
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.decreaseAllowance.selector, spender, subtractedValue));
        if (!success) {
            assertTrue(true); // revert allowed, cannot test return value
            return;
        }

        uint256 allowanceAfter = c.allowance(owner, spender);
        assertTrue(allowanceAfter == allowanceBefore - subtractedValue);
    }
}

